mapper.sql:
where 1=1

		and crpb_llave = #{llaveTabla}


		and crpb_estado = #{estado}


		and crpb_plantilla = #{plantilla}


		and crpb_nombre = #{nombre}


		and crpb_codigo = #{codigo}


		and brpb_soloexistente = #{soloExistenteFilter}


		and crpb_servidor = #{servidor}


		and brpb_publico = #{publicoFilter}


		and (upper(crpb_nombre) like upper('%' || #{filtroParametro} || '%'))
